export type ParsedPostCircularInstruction<
  TProgram extends string = typeof PENNY_POST_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>
  accounts: {
    sponsor: TAccountMetas[0]
    circular: TAccountMetas[1]
    potVault: TAccountMetas[2]
    sponsorToken: TAccountMetas[3]
    /** recorded on the circular, and pays their rent deposit back to it. */
    previousSponsor?: TAccountMetas[4] | undefined
    previousSponsorToken?: TAccountMetas[5] | undefined
    postOffice: TAccountMetas[6]
    postageMint: TAccountMetas[7]
    tokenProgram: TAccountMetas[8]
    systemProgram: TAccountMetas[9]
  }
  data: PostCircularInstructionData
}

export function parsePostCircularInstruction<TProgram extends string, TAccountMetas extends readonly AccountMeta[]>(
  instruction: Instruction<TProgram> & InstructionWithAccounts<TAccountMetas> & InstructionWithData<ReadonlyUint8Array>,
): ParsedPostCircularInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 10,
    })
  }
  let accountIndex = 0
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!
    accountIndex += 1
    return accountMeta
  }
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount()
    return accountMeta.address === PENNY_POST_PROGRAM_ADDRESS ? undefined : accountMeta
  }
  return {
    programAddress: instruction.programAddress,
    accounts: {
      sponsor: getNextAccount(),
      circular: getNextAccount(),
      potVault: getNextAccount(),
      sponsorToken: getNextAccount(),
      previousSponsor: getNextOptionalAccount(),
      previousSponsorToken: getNextOptionalAccount(),
      postOffice: getNextAccount(),
      postageMint: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getPostCircularInstructionDataDecoder().decode(instruction.data),
  }
}
